const intercept = -0.470497710312784;

// Fungsi tokenisasi (memecah kalimat jadi kata-kata, sama persis dengan default scikit-learn)
function tokenize(text) {
    const matches = text.toLowerCase().match(/\b\w\w+\b/g);
    return matches || [];
}

export function deteksiScam(text) {
    const tokens = tokenize(text);
    
    // 1. Hitung Term Frequency (TF)
    const tf = {};
    tokens.forEach(token => {
        if (vocabulary.hasOwnProperty(token)) {
            const idx = vocabulary[token];
            tf[idx] = (tf[idx] || 0) + 1;
        }
    });
    
    // 2. Hitung TF-IDF dan Terapkan Normalisasi L2 (Standar scikit-learn)
    let sumSquares = 0;
    const tfidf = {};
    for (const idx in tf) {
        const val = tf[idx] * idf[idx];
        tfidf[idx] = val;
        sumSquares += val * val;
    }
    
    const norm = Math.sqrt(sumSquares);
    if (norm > 0) {
        for (const idx in tfidf) {
            tfidf[idx] = tfidf[idx] / norm;
        }
    }
    
    // 3. Logistic Regression Prediksi (Perkalian bobot)
    let linearCombination = intercept;
    for (const idx in tfidf) {
        linearCombination += tfidf[idx] * coef[idx];
    }
    
    // 4. Hitung Probabilitas dengan Sigmoid
    const prob = 1 / (1 + Math.exp(-linearCombination));
    
    return {
        status: prob >= 0.5 ? 'SCAM' : 'AMAN',
        confidence: Number((Math.max(prob, 1 - prob) * 100).toFixed(1)), // Persentase keyakinan
        rawProbability: prob
    };
}
